from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient


class FHv1HttpClient(HttpClient):
    """ This class provides a client for the FH V1 API. """

    def __init__(self, base_url, connection_alias):
        super(FHv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/fh/v1"

    def get_real_time_measurements_info(self, timeout=30):
        endpoint = '/rmods/real-time-measurements/info'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def clear_rf_statistics_diagnostic_test_results(self, timeout=30):
        endpoint = '/diagnostic/rf-statistics-diagnostic-test/results'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_delete_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def reset_rmods(self, rmods_list, reset_reason, graceful_cell_shutdown, timeout):
        endpoint = '/rmods/operations/resets'
        headers = {
            "Content-Type": "application/json",
            "X-OAM-Client-Type": "em",
        }

        payload = {
            "ids": rmods_list,
            "resetReason": reset_reason,
            "gracefulCellShutdown": "true" if graceful_cell_shutdown else "false"
        }

        return self._send_post_request(endpoint=endpoint, timeout=timeout, headers=headers, json=payload)

    def get_status_of_reset_rmods(self, operation_id, timeout=30):
        endpoint = f'/rmods/operations/resets/{operation_id}'
        return self._send_get_request(endpoint=endpoint, timeout=timeout)

    def update_tx_power_thresholds(self, thresholds):
        endpoint = "/diagnostic/thresholds/tx-power"
        headers = {
            "accept": "application/json",
        }

        return self._send_put_request(endpoint=endpoint, headers=headers, json=thresholds)

    def set_ret_configuration(self, target_dn="", timeout=30, **kwargs):
        endpoint = '/alds/rets/operations/common-configuration'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }

        set_ret_configuration_data_item = {
            "targetDN": target_dn,
            "retUAliasLabel": kwargs.get('alias_label', ""),
            "deviceData": kwargs.get('device_data', ""),
            "antennaBearing": kwargs.get('antenna_bearing', ""),
            "maxAngle": kwargs.get('max_angle', ""),
            "mechanicalAngle": kwargs.get('mechanical_angle', ""),
            "minAngle": kwargs.get('min_angle', ""),
            "angle": kwargs.get('angle', ""),
            "calibration": kwargs.get('calibration', "false")
            }

        antenna_info_input = kwargs.get('antenna_info')
        if antenna_info_input:
            antenna_info = {
                "antennaModelNumber": antenna_info_input.get('model_number', ""),
                "antennaSerialNumber": antenna_info_input.get('serial_number', ""),
                "installationDate": antenna_info_input.get('installation_date', ""),
                "installerId": antenna_info_input.get('installer_id', ""),
                "baseStationId": antenna_info_input.get('base_station_id', ""),
                "sectorId": antenna_info_input.get('sector_id', "")
            }

            set_ret_configuration_data_item["antennaInfo"] = antenna_info

        return self._send_patch_request(endpoint=endpoint,
                                        headers=headers,
                                        payload=[set_ret_configuration_data_item],
                                        timeout=timeout)

    def get_ald_reset_status(self, operation_id, timeout=30):
        endpoint = f'/alds/operations/reset/{operation_id}'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json"
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

